import pillarGalleryManifest from "@/data/pillar-galleries.json";
import pillarVideoManifest from "@/data/pillar-videos.json";
import type { PublicGalleryImage } from "@/lib/public-gallery-image";

export type PillarKey = keyof typeof pillarGalleryManifest;

/** Photos per "Pillar of Change", generated by `scripts/update-gallery-manifest.mjs`. */
export const pillarGalleries = Object.fromEntries(
  Object.entries(pillarGalleryManifest).map(([key, images]) => [
    key,
    images.map((img) => ({ ...img, unoptimized: false })),
  ])
) as Record<PillarKey, PublicGalleryImage[]>;

/** Videos per "Pillar of Change", generated by `scripts/update-gallery-manifest.mjs`. */
export const pillarVideos = Object.fromEntries(
  (Object.keys(pillarGalleryManifest) as PillarKey[]).map((key) => [
    key,
    ((pillarVideoManifest as Partial<Record<PillarKey, Omit<PublicGalleryImage, "unoptimized">[]>>)[key] ?? []).map(
      (video) => ({ ...video, unoptimized: true, mediaType: "video" as const })
    ),
  ])
) as Record<PillarKey, PublicGalleryImage[]>;
